rows=list(ws.iter_rows(min_row=4, max_row=368, values_only=True))
# scan for anomalies vs neighbors
for i in range(1, len(rows)-1):
    v0=rows[i-1][1]; v1=rows[i][1]; v2=rows[i+1][1]
    if isinstance(v1,(int,float)):
        # ratio to neighbors
        for name, v in [('prev',v0),('next',v2)]:
            if isinstance(v,(int,float)) and v!=0:
                ratio=v1/v
                if ratio>3 or ratio<1/3:
                    print('anomaly row', i+4, rows[i], 'ratio to', name, ratio)
